        return addError(ew, err.parseInt());
    }

    function addError(
        ErrorsAndWarnings memory ew,
        StatusIssue err
    ) internal pure returns (ErrorsAndWarnings memory) {
        return addError(ew, err.parseInt());
    }

    function addWarning(
        uint16 warn
    ) internal pure returns (ErrorsAndWarnings memory) {
        ErrorsAndWarnings memory ew = ErrorsAndWarnings(
            new uint16[](0),
            new uint16[](0)
        );
        ew.warnings = pushMemory(ew.warnings, warn);
        return ew;
    }

    function addWarning(
        ErrorsAndWarnings memory ew,
