            );

        vm.expectRevert(abi.encodeWithSignature("UnusedItemParameters()"));
        context.consideration.fulfillBasicOrder(_basicOrderParameters);
    }

    function testRevertInvalidTimestamp(
        FuzzInputsCommon memory inputs
    ) public validateInputs(Context(consideration, inputs, 0)) {
        addErc721OfferItem(inputs.tokenId);
        addEthConsiderationItem(alice, inputs.paymentAmount);
        _configureBasicOrderParametersEthTo721(inputs);

        basicOrderParameters.startTime = block.timestamp + 1 days;
        basicOrderParameters.endTime = block.timestamp + 2 days;

        test(this.revertInvalidTimestamp, Context(consideration, inputs, 0));
        test(
            this.revertInvalidTimestamp,
            Context(referenceConsideration, inputs, 0)
        );
    }

    function revertInvalidTimestamp(Context memory context) external stateless {
        test721_1.mint(alice, context.args.tokenId);

        _configureOrderParameters(
            alice,
            address(0),
            bytes32(0),
            globalSalt++,
            false
        );
        baseOrderComponents.startTime = block.timestamp + 1 days;
        baseOrderComponents.endTime = block.timestamp + 2 days;

        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;

        vm.expectRevert(
            abi.encodeWithSelector(
                ConsiderationEventsAndErrors.InvalidTime.selector,
                basicOrderParameters.startTime,
                basicOrderParameters.endTime
            )
        );
        context.consideration.fulfillBasicOrder{
            value: context.args.paymentAmount
        }(basicOrderParameters);
    }

    function testRevertMissingOriginalConsiderationItems(
        FuzzInputsCommon memory inputs
    ) public validateInputs(Context(consideration, inputs, 0)) {
        addErc721OfferItem(inputs.tokenId);
        addEthConsiderationItem(alice, inputs.paymentAmount);

        _configureBasicOrderParametersEthTo721(inputs);
        basicOrderParameters.considerationAmount = inputs.paymentAmount;
        basicOrderParameters.totalOriginalAdditionalRecipients = 5;

        test(
            this.revertMissingOriginalConsiderationItems,
            Context(consideration, inputs, 0)
        );
        test(
            this.revertMissingOriginalConsiderationItems,
            Context(referenceConsideration, inputs, 0)
        );
    }

    function revertMissingOriginalConsiderationItems(
        Context memory context
    ) external stateless {
        test721_1.mint(alice, context.args.tokenId);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;

        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;

        vm.expectRevert(
            abi.encodeWithSelector(
                ConsiderationEventsAndErrors
                    .MissingOriginalConsiderationItems
                    .selector
            )
        );
        context.consideration.fulfillBasicOrder{
            value: context.args.paymentAmount
        }(basicOrderParameters);
    }

    function prepareBasicOrder(
        uint256 tokenId
    )
        internal
        returns (
            Order memory order,
            BasicOrderParameters memory _basicOrderParameters
        )
    {
        (Order memory _order, , ) = _prepareOrder(tokenId, 1);
        order = _order;
        _basicOrderParameters = toBasicOrderParameters(
            _order,
            BasicOrderType.ERC20_TO_ERC1155_FULL_OPEN
        );
    }

    function basicErc20To1155(Context memory context) external stateless {
        test1155_1.mint(alice, context.args.tokenId, context.tokenAmount);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            context.args.useConduit ? conduitKeyOne : bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;
        context.consideration.fulfillBasicOrder(basicOrderParameters);
        assertEq(
            context.tokenAmount,
            test1155_1.balanceOf(address(this), context.args.tokenId)
        );
    }

    function basicEthTo1155(Context memory context) external stateless {
        test1155_1.mint(alice, context.args.tokenId, context.tokenAmount);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            context.args.useConduit ? conduitKeyOne : bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;
        context.consideration.fulfillBasicOrder{
            value: context.args.paymentAmount
        }(basicOrderParameters);
        assertEq(
            context.tokenAmount,
            test1155_1.balanceOf(address(this), context.args.tokenId)
        );
    }

    function basicEthTo721(Context memory context) external stateless {
        test721_1.mint(alice, context.args.tokenId);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            context.args.useConduit ? conduitKeyOne : bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;
        context.consideration.fulfillBasicOrder{
            value: context.args.paymentAmount
        }(basicOrderParameters);
        assertEq(address(this), test721_1.ownerOf(context.args.tokenId));
    }

    function basicEthTo721Efficient(Context memory context) external stateless {
        test721_1.mint(alice, context.args.tokenId);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            context.args.useConduit ? conduitKeyOne : bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;
        context.consideration.fulfillBasicOrder_efficient_6GL6yc{
            value: context.args.paymentAmount
        }(basicOrderParameters);
        assertEq(address(this), test721_1.ownerOf(context.args.tokenId));
    }

    function basicEthTo721WithAdditionalRecipients(
        Context memory context
    ) external stateless {
        test721_1.mint(alice, context.args.tokenId);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            context.args.useConduit ? conduitKeyOne : bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;

        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;

        uint256 aliceBalanceBefore = alice.balance;

        context.consideration.fulfillBasicOrder{
            value: context.args.paymentAmount.mul(10000000)
        }(basicOrderParameters);

        uint256 aliceBalanceAfter = alice.balance;

        assertEq(address(this), test721_1.ownerOf(context.args.tokenId));
        assertEq(
            1 +
                (context.args.paymentAmount % 1000) *
                basicOrderParameters.additionalRecipients.length,
            aliceBalanceAfter - aliceBalanceBefore
        );
    }

    function basicErc20To721(Context memory context) external stateless {
        test721_1.mint(alice, context.args.tokenId);

        configureOrderComponents(
            context.args.zone,
            context.args.zoneHash,
            context.args.salt,
            context.args.useConduit ? conduitKeyOne : bytes32(0)
        );
        uint256 counter = context.consideration.getCounter(alice);
        baseOrderComponents.counter = counter;
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        basicOrderParameters.signature = signature;
        context.consideration.fulfillBasicOrder(basicOrderParameters);
        assertEq(
            context.args.paymentAmount.add(uint128(MAX_INT)),
            token1.balanceOf(address(alice))
        );
        assertEq(address(this), test721_1.ownerOf(context.args.tokenId));
    }

    function _configureBasicOrderParametersEthTo721(
        FuzzInputsCommon memory args
    ) internal {
        basicOrderParameters.considerationToken = address(0);
        basicOrderParameters.considerationIdentifier = 0;
        basicOrderParameters.considerationAmount = args.paymentAmount;
        basicOrderParameters.offerer = payable(alice);
        basicOrderParameters.zone = args.zone;
        basicOrderParameters.offerToken = address(test721_1);
        basicOrderParameters.offerIdentifier = args.tokenId;
        basicOrderParameters.offerAmount = 1;
        basicOrderParameters.basicOrderType = BasicOrderType
            .ETH_TO_ERC721_FULL_OPEN;
        basicOrderParameters.startTime = block.timestamp;
        basicOrderParameters.endTime = block.timestamp + 100;
        basicOrderParameters.zoneHash = args.zoneHash;
        basicOrderParameters.salt = args.salt;
        basicOrderParameters.offererConduitKey = args.useConduit
            ? conduitKeyOne
            : bytes32(0);
        basicOrderParameters.fulfillerConduitKey = bytes32(0);
        basicOrderParameters.totalOriginalAdditionalRecipients = 0;
        // additional recipients should always be empty
        // don't do signature;
    }

    function _configureBasicOrderParametersEthTo1155(
        FuzzInputsCommon memory args,
        uint128 amount
    ) internal {
        basicOrderParameters.considerationToken = address(0);
        basicOrderParameters.considerationIdentifier = 0;
        basicOrderParameters.considerationAmount = args.paymentAmount;
        basicOrderParameters.offerer = payable(alice);
        basicOrderParameters.zone = args.zone;
        basicOrderParameters.offerToken = address(test1155_1);
        basicOrderParameters.offerIdentifier = args.tokenId;
        basicOrderParameters.offerAmount = amount;
        basicOrderParameters.basicOrderType = BasicOrderType
            .ETH_TO_ERC1155_FULL_OPEN;
        basicOrderParameters.startTime = block.timestamp;
        basicOrderParameters.endTime = block.timestamp + 100;
        basicOrderParameters.zoneHash = args.zoneHash;
        basicOrderParameters.salt = args.salt;
        basicOrderParameters.offererConduitKey = args.useConduit
            ? conduitKeyOne
            : bytes32(0);
        basicOrderParameters.fulfillerConduitKey = bytes32(0);
        basicOrderParameters.totalOriginalAdditionalRecipients = 0;
        // additional recipients should always be empty
        // don't do signature;
    }

    function _configureBasicOrderParametersErc20To1155(
        FuzzInputsCommon memory args,
        uint128 amount
    ) internal {
        _configureBasicOrderParametersEthTo1155(args, amount);
        basicOrderParameters.considerationToken = address(token1);
        basicOrderParameters.basicOrderType = BasicOrderType
            .ERC20_TO_ERC1155_FULL_OPEN;
    }

    function _configureBasicOrderParametersErc20To721(
        FuzzInputsCommon memory args
    ) internal {
        _configureBasicOrderParametersEthTo721(args);
        basicOrderParameters.considerationToken = address(token1);
        basicOrderParameters.basicOrderType = BasicOrderType
            .ERC20_TO_ERC721_FULL_OPEN;
    }

    function configureOrderComponents(
        address zone,
        bytes32 zoneHash,
        uint256 salt,
        bytes32 conduitKey
    ) internal {
        baseOrderComponents.offerer = alice;
        baseOrderComponents.zone = zone;
        baseOrderComponents.offer = offerItems;
        baseOrderComponents.consideration = considerationItems;
        baseOrderComponents.orderType = OrderType.FULL_OPEN;
        baseOrderComponents.startTime = block.timestamp;
        baseOrderComponents.endTime = block.timestamp + 100;
        baseOrderComponents.zoneHash = zoneHash;
        baseOrderComponents.salt = salt;
        baseOrderComponents.conduitKey = conduitKey;
        // don't set counter
    }
}

test/foundry/FulfillOrderTest.t.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.17;

import {
    ItemType,
    OrderType
} from "seaport-types/src/lib/ConsiderationEnums.sol";

import {
    ConsiderationInterface
} from "seaport-types/src/interfaces/ConsiderationInterface.sol";

import {
    ConsiderationItem,
    OfferItem,
    Order,
    OrderComponents,
    OrderParameters
} from "seaport-types/src/lib/ConsiderationStructs.sol";

import { BaseOrderTest } from "./utils/BaseOrderTest.sol";

import { ArithmeticUtil } from "./utils/ArithmeticUtil.sol";

contract FulfillOrderTest is BaseOrderTest {
    using ArithmeticUtil for uint256;
    using ArithmeticUtil for uint128;
    using ArithmeticUtil for uint120;
    using ArithmeticUtil for uint8;

    FuzzInputsCommon empty;
    bytes signature1271;

    uint256 badIdentifier;
    address badToken;
    struct FuzzInputsCommon {
        address zone;
        uint128 id;
        bytes32 zoneHash;
        uint256 salt;
        uint128[3] paymentAmts;
        bool useConduit;
        uint120 startAmount;
        uint120 endAmount;
        uint16 warpAmount;
    }

    struct Context {
        ConsiderationInterface consideration;
        FuzzInputsCommon args;
        uint256 erc1155Amt;
        uint128 tipAmt;
        uint8 numTips;
    }

    function test(
        function(Context memory) external fn,
        Context memory context
    ) internal {
        try fn(context) {} catch (bytes memory reason) {
            assertPass(reason);
        }
    }

    modifier validateInputs(FuzzInputsCommon memory args) {
        vm.assume(
            args.paymentAmts[0] > 0 &&
                args.paymentAmts[1] > 0 &&
                args.paymentAmts[2] > 0
        );
        vm.assume(
            args.paymentAmts[0].add(args.paymentAmts[1]).add(
                args.paymentAmts[2]
            ) <= uint128(MAX_INT)
        );
        _;
    }

    modifier validateInputsWithTip(
        FuzzInputsCommon memory args,
        uint256 tipAmt
    ) {
        vm.assume(
            args.paymentAmts[0] > 0 &&
                args.paymentAmts[1] > 0 &&
                args.paymentAmts[2] > 0 &&
                tipAmt > 0
        );
        vm.assume(
            args
                .paymentAmts[0]
                .add(args.paymentAmts[1])
                .add(args.paymentAmts[2])
                .add(tipAmt) <= uint128(MAX_INT)
        );
        _;
    }

    modifier validateInputsWithMultipleTips(
        FuzzInputsCommon memory args,
        uint256 numTips
    ) {
        {
            numTips = (numTips % 64) + 1;
            vm.assume(
                args.paymentAmts[0] > 0 &&
                    args.paymentAmts[1] > 0 &&
                    args.paymentAmts[2] > 0
            );
            vm.assume(
                args
                    .paymentAmts[0]
                    .add(args.paymentAmts[1])
                    .add(args.paymentAmts[2])
                    .add(numTips.mul(numTips + 1).div(2)) <= uint128(MAX_INT)
            );
        }
        _;
    }

    function testNoNativeOffers(uint8[8] memory itemTypes) public {
        uint256 tokenId;
        for (uint256 i; i < 8; i++) {
            ItemType itemType = ItemType(itemTypes[i] % 4);
            if (itemType == ItemType.NATIVE) {
                addEthOfferItem(1);
            } else if (itemType == ItemType.ERC20) {
                addErc20OfferItem(1);
            } else if (itemType == ItemType.ERC1155) {
                test1155_1.mint(alice, tokenId, 1);
                addErc1155OfferItem(tokenId, 1);
            } else {
                test721_1.mint(alice, tokenId);
                addErc721OfferItem(tokenId);
            }
            tokenId++;
        }
        addEthOfferItem(1);

        addEthConsiderationItem(alice, 1);

        test(this.noNativeOfferItems, Context(consideration, empty, 0, 0, 0));
        test(
            this.noNativeOfferItems,
            Context(referenceConsideration, empty, 0, 0, 0)
        );
    }

    function noNativeOfferItems(Context memory context) external stateless {
        configureOrderParameters(alice);
        uint256 counter = context.consideration.getCounter(alice);
        configureOrderComponents(counter);
        bytes32 orderHash = context.consideration.getOrderHash(
            baseOrderComponents
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            orderHash
        );

        vm.expectRevert(abi.encodeWithSignature("InvalidNativeOfferItem()"));

        context.consideration.fulfillOrder{ value: 1 ether }(
            Order(baseOrderParameters, signature),
            bytes32(0)
        );
    }

    function testNullAddressSpendReverts() public {
        // mint token to null address
        preapproved721.mint(address(0), 1);
        // mint erc token to test address
        token1.mint(address(this), 1);
        // offer burnt erc721
        addErc721OfferItem(address(preapproved721), 1);
        // consider erc20 to null address
        addErc20ConsiderationItem(payable(0), 1);
        // configure baseOrderParameters with null address as offerer
        configureOrderParameters(address(0));
        test(
            this.nullAddressSpendReverts,
            Context(referenceConsideration, empty, 0, 0, 0)
        );
        test(
            this.nullAddressSpendReverts,
            Context(consideration, empty, 0, 0, 0)
        );
    }

    function nullAddressSpendReverts(
        Context memory context
    ) external stateless {
        // create a bad signature
        bytes memory signature = abi.encodePacked(
            bytes32(0),
            bytes32(0),
            bytes1(uint8(27))
        );
        // test that signature is recognized as invalid even though signer recovered is null address
        vm.expectRevert(abi.encodeWithSignature("InvalidSigner()"));

        context.consideration.fulfillOrder(
            Order(baseOrderParameters, signature),
            bytes32(0)
        );
    }

    function testFulfillAscendingDescendingOffer(
        FuzzInputsCommon memory inputs
    ) public validateInputs(inputs) onlyPayable(inputs.zone) {
        vm.assume(inputs.startAmount > 0 && inputs.endAmount > 0);
        inputs.warpAmount %= 1000;
        test(
            this.fulfillAscendingDescendingOffer,
            Context(referenceConsideration, inputs, 0, 0, 0)
        );
        test(
            this.fulfillAscendingDescendingOffer,
            Context(consideration, inputs, 0, 0, 0)
        );
    }

    function fulfillAscendingDescendingOffer(
        Context memory context
    ) external stateless {
        bytes32 conduitKey = context.args.useConduit
            ? conduitKeyOne
            : bytes32(0);
        token1.mint(
            alice,
            (
                context.args.endAmount > context.args.startAmount
                    ? context.args.endAmount
                    : context.args.startAmount
            ).mul(1000)
        );
        addErc20OfferItem(
            context.args.startAmount.mul(1000),
            context.args.endAmount.mul(1000)
        );
        addEthConsiderationItem(alice, 1000);
        OrderParameters memory orderParameters = OrderParameters(
            alice,
            context.args.zone,
            offerItems,
            considerationItems,
            OrderType.FULL_OPEN,
            block.timestamp,
            block.timestamp + 1000,
            bytes32(0),
            context.args.salt,
            conduitKey,
            1
        );

        OrderComponents memory orderComponents = getOrderComponents(
            orderParameters,
            context.consideration.getCounter(alice)
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            context.consideration.getOrderHash(orderComponents)
        );

        uint256 startTime = block.timestamp;
        vm.warp(block.timestamp + context.args.warpAmount);
        uint256 expectedAmount = _locateCurrentAmount(
            context.args.startAmount.mul(1000),
            context.args.endAmount.mul(1000),
            startTime,
            startTime + 1000,
            false // don't round up offers
        );
        vm.expectEmit(true, true, false, true, address(token1));
        emit Transfer(alice, address(this), expectedAmount);
        context.consideration.fulfillOrder{ value: 1000 }(
            Order(orderParameters, signature),
            conduitKey
        );
    }

    function testFulfillAscendingDescendingConsideration(
        FuzzInputsCommon memory inputs,
        uint256 erc1155Amt
    ) public validateInputs(inputs) onlyPayable(inputs.zone) {
        vm.assume(inputs.startAmount > 0 && inputs.endAmount > 0);
        vm.assume(erc1155Amt > 0);
        test(
            this.fulfillAscendingDescendingConsideration,
            Context(referenceConsideration, inputs, erc1155Amt, 0, 0)
        );
        test(
            this.fulfillAscendingDescendingConsideration,
            Context(consideration, inputs, erc1155Amt, 0, 0)
        );
    }

    function fulfillAscendingDescendingConsideration(
        Context memory context
    ) external stateless {
        context.args.warpAmount %= 1000;
        bytes32 conduitKey = context.args.useConduit
            ? conduitKeyOne
            : bytes32(0);

        test1155_1.mint(alice, context.args.id, context.erc1155Amt);
        addErc1155OfferItem(context.args.id, context.erc1155Amt);

        addErc20ConsiderationItem(
            alice,
            context.args.startAmount.mul(1000),
            context.args.endAmount.mul(1000)
        );
        OrderParameters memory orderParameters = OrderParameters(
            alice,
            context.args.zone,
            offerItems,
            considerationItems,
            OrderType.FULL_OPEN,
            block.timestamp,
            block.timestamp + 1000,
            bytes32(0),
            context.args.salt,
            conduitKey,
            1
        );
        delete offerItems;
        delete considerationItems;

        OrderComponents memory orderComponents = getOrderComponents(
            orderParameters,
            context.consideration.getCounter(alice)
        );
        bytes memory signature = signOrder(
            context.consideration,
            alicePk,
            context.consideration.getOrderHash(orderComponents)
        );

        uint256 startTime = block.timestamp;
        vm.warp(block.timestamp + context.args.warpAmount);
        uint256 expectedAmount = _locateCurrentAmount(
            context.args.startAmount.mul(1000),
            context.args.endAmount.mul(1000),
            startTime,
            startTime + 1000,
            true // round up considerations
        );
        token1.mint(address(this), expectedAmount);
        vm.expectEmit(true, true, false, true, address(token1));
        emit Transfer(address(this), address(alice), expectedAmount);
        context.consideration.fulfillOrder(
            Order(orderParameters, signature),
            conduitKey
        );
    }

    function testFulfillOrderEthToErc721(
        FuzzInputsCommon memory inputs
    ) public validateInputs(inputs) onlyPayable(inputs.zone) {
        test(
            this.fulfillOrderEthToErc721,
            Context(referenceConsideration, inputs, 0, 0, 0)
        );
        test(
            this.fulfillOrderEthToErc721,
            Context(consideration, inputs, 0, 0, 0)
        );
    }

    function testFulfillOrderEthToErc1155(
        FuzzInputsCommon memory inputs,
        uint256 tokenAmount
    ) public validateInputs(inputs) onlyPayable(inputs.zone) {
        vm.assume(tokenAmount > 0);
        test(
            this.fulfillOrderEthToErc1155,
            Context(referenceConsideration, inputs, tokenAmount, 0, 0)
        );
        test(
            this.fulfillOrderEthToErc1155,
            Context(consideration, inputs, tokenAmount, 0, 0)
        );
    }

    function testFulfillOrderEthToErc721WithSingleTip(
        FuzzInputsCommon memory inputs,
        uint128 tipAmt
    ) public onlyPayable(inputs.zone) {
        vm.assume(
            inputs.paymentAmts[0] > 0 &&
                inputs.paymentAmts[1] > 0 &&
                inputs.paymentAmts[2] > 0 &&
                tipAmt > 0
        );
        vm.assume(
            inputs.paymentAmts[0].add(inputs.paymentAmts[1]).add(
                inputs.paymentAmts[2].add(tipAmt)
            ) <= uint128(MAX_INT)
        );
        test(
            this.fulfillOrderEthToErc721WithSingleEthTip,
            Context(referenceConsideration, inputs, 0, tipAmt, 0)
        );
        test(
            this.fulfillOrderEthToErc721WithSingleEthTip,
            Context(consideration, inputs, 0, tipAmt, 0)
        );
    }

    function testFulfillOrderEthToErc1155WithSingleTip(
        FuzzInputsCommon memory inputs,
        uint256 tokenAmt,
        uint128 tipAmt
    ) public onlyPayable(inputs.zone) {
        vm.assume(tokenAmt > 0);
        vm.assume(
            inputs.paymentAmts[0] > 0 &&
                inputs.paymentAmts[1] > 0 &&
                inputs.paymentAmts[2] > 0 &&
                tipAmt > 0
        );
        vm.assume(
            inputs.paymentAmts[0].add(inputs.paymentAmts[1]).add(
                inputs.paymentAmts[2].add(tipAmt)
            ) <= uint128(MAX_INT)
        );
        test(
            this.fulfillOrderEthToErc1155WithSingleEthTip,
            Context(referenceConsideration, inputs, tokenAmt, tipAmt, 0)
        );
        test(
