        );
    }
    if (outputSelection.expectedEvents) {
        jsonOut = context
            .expectations
            .allExpectedExecutions
            .serializeTransferLogs("root", "expectedEvents", context);
    }
    /*if (outputSelection.returnValues) {
        jsonOut = Searializer.tojsonReturnValues(
