// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import { Test } from "forge-std/Test.sol";

import {
    ExecutionLib,
    ZoneParametersLib
} from "seaport-sol/src/SeaportSol.sol";

import {
    AdvancedOrder,
    ConsiderationItem,
    Execution,
    OrderParameters,
    ReceivedItem,
    SpentItem
} from "seaport-sol/src/SeaportStructs.sol";

import { OrderDetails } from "seaport-sol/src/fulfillments/lib/Structs.sol";

import { ItemType, OrderType } from "seaport-sol/src/SeaportEnums.sol";

import { UnavailableReason } from "seaport-sol/src/SpaceEnums.sol";

import { FuzzTestContext } from "./FuzzTestContextLib.sol";

import { CriteriaResolverHelper } from "./CriteriaResolverHelper.sol";

import {
    AmountDeriverHelper
} from "seaport-sol/src/lib/fulfillment/AmountDeriverHelper.sol";

import { ExpectedEventsUtil } from "./event-utils/ExpectedEventsUtil.sol";

import { ExecutionsFlattener } from "./event-utils/ExecutionsFlattener.sol";

import { ExpectedBalances } from "./ExpectedBalances.sol";

import { dumpExecutions } from "./DebugUtil.sol";

import { FuzzChecks } from "./FuzzChecks.sol";

import { FuzzEngineLib } from "./FuzzEngineLib.sol";

import { FuzzHelpers } from "./FuzzHelpers.sol";

import { FuzzTestContext } from "./FuzzTestContextLib.sol";

interface TestERC20 {
    function mint(address to, uint256 amount) external;

    function increaseAllowance(address spender, uint256 amount) external;
}

interface TestERC721 {
    function mint(address to, uint256 tokenId) external;

    function setApprovalForAll(address operator, bool approved) external;
}

interface TestERC1155 {
    function mint(address to, uint256 tokenId, uint256 amount) external;

    function setApprovalForAll(address operator, bool approved) external;
}

/**
 *  @dev Stateless helpers related to fuzz checks.
 */
library CheckHelpers {
    /**
     *  @dev Register a check to be run after the test is executed.
     *
     * @param context The test context.
     * @param check   The check to register.
     *
     * @return The updated test context.
     */
    function registerCheck(
        FuzzTestContext memory context,
        bytes4 check
    ) internal pure returns (FuzzTestContext memory) {
        bytes4[] memory checks = context.checks;
        bytes4[] memory newChecks = new bytes4[](checks.length + 1);
        for (uint256 i; i < checks.length; ++i) {
            newChecks[i] = checks[i];
        }
        newChecks[checks.length] = check;
        context.checks = newChecks;
        return context;
    }

    /**
     *  @dev Get the address to approve to for a given test context.
     *
     * @param context The test context.
     */
    function getApproveTo(
        FuzzTestContext memory context
    ) internal view returns (address) {
        if (context.executionState.fulfillerConduitKey == bytes32(0)) {
            return address(context.seaport);
        } else {
            (address conduit, bool exists) = context
                .conduitController
                .getConduit(context.executionState.fulfillerConduitKey);
            if (exists) {
                return conduit;
            } else {
                revert("CheckHelpers: Conduit not found");
            }
        }
    }

    /**
     *  @dev Get the address to approve to for a given test context and order.
     *
     * @param context The test context.
     * @param orderParams The order parameters.
     */
    function getApproveTo(
        FuzzTestContext memory context,
        OrderParameters memory orderParams
    ) internal view returns (address) {
        if (orderParams.conduitKey == bytes32(0)) {
            return address(context.seaport);
        } else {
            (address conduit, bool exists) = context
                .conduitController
                .getConduit(orderParams.conduitKey);
            if (exists) {
                return conduit;
            } else {
                revert("CheckHelpers: Conduit not found");
            }
        }
    }

    /**
     *  @dev Get the address to approve to for a given test context and order.
     *
     * @param context The test context.
     * @param orderDetails The order details.
     */
    function getApproveTo(
        FuzzTestContext memory context,
        OrderDetails memory orderDetails
    ) internal view returns (address) {
        if (orderDetails.conduitKey == bytes32(0)) {
            return address(context.seaport);
        } else {
            (address conduit, bool exists) = context
                .conduitController
                .getConduit(orderDetails.conduitKey);
            if (exists) {
                return conduit;
            } else {
                revert("CheckHelpers: Conduit not found");
            }
        }
    }
}

/**
 *  @dev Setup functions perform the stateful setup steps necessary to run a
 *       FuzzEngine test, like minting test tokens and setting approvals.
 *       Currently, we also register checks in the setup step, but we might
 *       want to move this to a separate step. Setup happens after generation,
 *       amendment, and derivation, but before execution.
 */
abstract contract FuzzSetup is Test, AmountDeriverHelper {
    using CheckHelpers for FuzzTestContext;
    using FuzzEngineLib for FuzzTestContext;
    using FuzzHelpers for FuzzTestContext;

    using FuzzHelpers for AdvancedOrder[];
    using ZoneParametersLib for AdvancedOrder[];

    using ExecutionLib for Execution;

    using ExpectedEventsUtil for FuzzTestContext;

    /**
     *  @dev Set up the zone params on a test context.
     *
     * @param context The test context.
     */
    function setUpZoneParameters(FuzzTestContext memory context) public view {
        UnavailableReason[] memory unavailableReasons = new UnavailableReason[](
            context.advancedOrdersSpace.orders.length
        );

        for (uint256 i; i < context.executionState.orderDetails.length; ++i) {
            unavailableReasons[i] = context
                .executionState
                .orderDetails[i]
                .unavailableReason;
        }

        // Get the expected zone calldata hashes for each order.
        bytes32[] memory calldataHashes = context
            .executionState
            .orders
            .getExpectedZoneCalldataHash(
                address(context.seaport),
                context.executionState.caller,
                context.executionState.criteriaResolvers,
                context.executionState.maximumFulfilled,
                unavailableReasons
            );

        // Provision the expected zone calldata hash array.
        bytes32[] memory expectedZoneCalldataHash = new bytes32[](
            context.executionState.orders.length
        );

        bool registerChecks;

        // Iterate over the orders and for each restricted order, set up the
        // expected zone calldata hash. If any of the orders is restricted,
        // flip the flag to register the hash validation check.
        for (uint256 i = 0; i < context.executionState.orders.length; ++i) {
            OrderParameters memory order = context
                .executionState
                .orders[i]
                .parameters;
            if (
                context.executionState.orderDetails[i].unavailableReason ==
                UnavailableReason.AVAILABLE &&
                (order.orderType == OrderType.FULL_RESTRICTED ||
                    order.orderType == OrderType.PARTIAL_RESTRICTED)
            ) {
                registerChecks = true;
                expectedZoneCalldataHash[i] = calldataHashes[i];
            }
        }

        context
            .expectations
            .expectedZoneCalldataHash = expectedZoneCalldataHash;

        if (registerChecks) {
            context.registerCheck(
                FuzzChecks.check_validateOrderExpectedDataHash.selector
            );
        }
    }

    function setUpContractOfferers(FuzzTestContext memory context) public pure {
        bytes32[2][] memory contractOrderCalldataHashes = context
            .getExpectedContractOffererCalldataHashes();

        bytes32[2][]
            memory expectedContractOrderCalldataHashes = new bytes32[2][](
                context.executionState.orders.length
            );

        bool registerChecks;

        for (uint256 i = 0; i < context.executionState.orders.length; ++i) {
            OrderParameters memory order = context
                .executionState
                .orders[i]
                .parameters;
            if (
                context.executionState.orderDetails[i].unavailableReason ==
                UnavailableReason.AVAILABLE &&
                order.orderType == OrderType.CONTRACT
            ) {
                registerChecks = true;
                expectedContractOrderCalldataHashes[i][
                    0
                ] = contractOrderCalldataHashes[i][0];
                expectedContractOrderCalldataHashes[i][
                    1
                ] = contractOrderCalldataHashes[i][1];
            }
        }

        context
            .expectations
            .expectedContractOrderCalldataHashes = expectedContractOrderCalldataHashes;

        if (registerChecks) {
            context.registerCheck(
                FuzzChecks.check_contractOrderExpectedDataHashes.selector
            );
        }
    }

    /**
     *  @dev Set up the offer items on a test context. Mints test tokens and
     *       sets necessary approvals.
     *
     * @param context The test context.
     */
    function setUpOfferItems(FuzzTestContext memory context) public {
        bool isMatchable = context.action() ==
            context.seaport.matchAdvancedOrders.selector ||
            context.action() == context.seaport.matchOrders.selector;

        // Iterate over orders and mint/approve as necessary.
        for (uint256 i; i < context.executionState.orderDetails.length; ++i) {
            OrderDetails memory order = context.executionState.orderDetails[i];

            if (order.unavailableReason != UnavailableReason.AVAILABLE) {
                continue;
            }

            SpentItem[] memory items = order.offer;
            address offerer = order.offerer;
            address approveTo = context.getApproveTo(order);
            for (uint256 j = 0; j < items.length; j++) {
                SpentItem memory item = items[j];

                if (item.itemType == ItemType.NATIVE) {
                    if (
                        context.executionState.orders[i].parameters.orderType ==
                        OrderType.CONTRACT
                    ) {
                        vm.deal(offerer, offerer.balance + item.amount);
                    } else if (isMatchable) {
                        vm.deal(
                            context.executionState.caller,
                            context.executionState.caller.balance + item.amount
                        );
                    }
                }

                if (item.itemType == ItemType.ERC20) {
                    TestERC20(item.token).mint(offerer, item.amount);
                    vm.prank(offerer);
                    TestERC20(item.token).increaseAllowance(
                        approveTo,
                        item.amount
                    );
                }

                if (item.itemType == ItemType.ERC721) {
                    TestERC721(item.token).mint(offerer, item.identifier);
                    vm.prank(offerer);
                    TestERC721(item.token).setApprovalForAll(approveTo, true);
                }

                if (item.itemType == ItemType.ERC1155) {
                    TestERC1155(item.token).mint(
                        offerer,
                        item.identifier,
                        item.amount
                    );
                    vm.prank(offerer);
                    TestERC1155(item.token).setApprovalForAll(approveTo, true);
                }
            }
        }
    }

    /**
     *  @dev Set up the consideration items on a test context. Mints test tokens
     *       and sets necessary approvals.
     *
     * @param context The test context.
     */
    function setUpConsiderationItems(FuzzTestContext memory context) public {
        // Skip creating consideration items if we're calling a match function
        if (
            context.action() == context.seaport.matchAdvancedOrders.selector ||
            context.action() == context.seaport.matchOrders.selector
        ) return;

        // In all cases, deal balance to caller if consideration item is native
        for (uint256 i; i < context.executionState.orderDetails.length; ++i) {
            OrderDetails memory order = context.executionState.orderDetails[i];
            ReceivedItem[] memory items = order.consideration;

            for (uint256 j = 0; j < items.length; j++) {
                if (items[j].itemType == ItemType.NATIVE) {
                    vm.deal(
                        context.executionState.caller,
                        context.executionState.caller.balance + items[j].amount
                    );
                }
            }
        }

        // Special handling for basic orders that are bids; only first item
        // needs to be approved
        if (
            (context.action() == context.seaport.fulfillBasicOrder.selector ||
                context.action() ==
                context.seaport.fulfillBasicOrder_efficient_6GL6yc.selector) &&
            context.executionState.orders[0].parameters.offer[0].itemType ==
            ItemType.ERC20
        ) {
            ConsiderationItem memory item = context
                .executionState
                .orders[0]
                .parameters
                .consideration[0];

            address approveTo = context.getApproveTo();

            if (item.itemType == ItemType.ERC721) {
                TestERC721(item.token).mint(
                    context.executionState.caller,
                    item.identifierOrCriteria
                );
                vm.prank(context.executionState.caller);
                TestERC721(item.token).setApprovalForAll(approveTo, true);
            } else {
                TestERC1155(item.token).mint(
                    context.executionState.caller,
                    item.identifierOrCriteria,
                    item.startAmount
                );
                vm.prank(context.executionState.caller);
                TestERC1155(item.token).setApprovalForAll(approveTo, true);
            }

            return;
        }

        // Iterate over orders and mint/approve as necessary.
        for (uint256 i; i < context.executionState.orderDetails.length; ++i) {
            OrderDetails memory order = context.executionState.orderDetails[i];
            ReceivedItem[] memory items = order.consideration;

            if (order.unavailableReason != UnavailableReason.AVAILABLE) {
                continue;
            }

            address owner = context.executionState.caller;
            address approveTo = context.getApproveTo();

            for (uint256 j = 0; j < items.length; j++) {
                ReceivedItem memory item = items[j];

                if (item.itemType == ItemType.ERC20) {
                    TestERC20(item.token).mint(owner, item.amount);
                    vm.prank(owner);
                    TestERC20(item.token).increaseAllowance(
                        approveTo,
                        item.amount
                    );
                }

                if (item.itemType == ItemType.ERC721) {
                    bool shouldMint = true;
                    if (
                        context.executionState.caller ==
                        context.executionState.recipient ||
                        context.executionState.recipient == address(0)
                    ) {
                        for (
                            uint256 k;
                            k < context.executionState.orderDetails.length;
                            ++k
                        ) {
                            if (
                                context
                                    .executionState
                                    .orderDetails[k]
                                    .unavailableReason !=
                                UnavailableReason.AVAILABLE
                            ) {
                                continue;
                            }

                            SpentItem[] memory spentItems = context
                                .executionState
                                .orderDetails[k]
                                .offer;
                            for (uint256 l; l < spentItems.length; ++l) {
                                if (
                                    spentItems[l].itemType == ItemType.ERC721 &&
                                    spentItems[l].token == item.token &&
                                    spentItems[l].identifier == item.identifier
                                ) {
                                    shouldMint = false;
                                    break;
                                }
                            }
                            if (!shouldMint) break;
                        }
                    }
                    if (shouldMint) {
                        TestERC721(item.token).mint(owner, item.identifier);
                    }
                    vm.prank(owner);
                    TestERC721(item.token).setApprovalForAll(approveTo, true);
                }

                if (item.itemType == ItemType.ERC1155) {
                    TestERC1155(item.token).mint(
                        owner,
                        item.identifier,
                        item.amount
                    );
                    vm.prank(owner);
                    TestERC1155(item.token).setApprovalForAll(approveTo, true);
                }
            }
        }
    }

    function registerExpectedEventsAndBalances(
        FuzzTestContext memory context
    ) public {
        ExecutionsFlattener.flattenExecutions(context);
        context.registerCheck(FuzzChecks.check_expectedBalances.selector);
        ExpectedBalances balanceChecker = context.testHelpers.balanceChecker();

        Execution[] memory _executions = context
            .expectations
            .allExpectedExecutions;
        Execution[] memory executions = _executions;

        try balanceChecker.addTransfers(executions) {} catch (
            bytes memory reason
        ) {
            context.expectations.allExpectedExecutions = executions;
            dumpExecutions(context);
            assembly {
                revert(add(reason, 32), mload(reason))
            }
        }
        context.registerCheck(FuzzChecks.check_executions.selector);
        context.setExpectedTransferEventHashes();
        context.registerCheck(
            FuzzChecks.check_expectedTransferEventsEmitted.selector
        );
        ExpectedEventsUtil.startRecordingLogs();
    }

    /**
     * @dev Set up the checks that will always be run. Note that this must be
     *      run after registerExpectedEventsAndBalances at the moment.
     *
     * @param context The test context.
     */
    function registerCommonChecks(FuzzTestContext memory context) public {
        context.setExpectedSeaportEventHashes();
        context.registerCheck(
            FuzzChecks.check_expectedSeaportEventsEmitted.selector
        );
        context.registerCheck(FuzzChecks.check_orderStatusFullyFilled.selector);
    }

    /**
     *  @dev Set up the function-specific checks.
     *
     * @param context The test context.
     */
    function registerFunctionSpecificChecks(
        FuzzTestContext memory context
    ) public view {
        bytes4 _action = context.action();
        if (_action == context.seaport.fulfillOrder.selector) {
            context.registerCheck(FuzzChecks.check_orderFulfilled.selector);
        } else if (_action == context.seaport.fulfillAdvancedOrder.selector) {
            context.registerCheck(FuzzChecks.check_orderFulfilled.selector);
        } else if (_action == context.seaport.fulfillBasicOrder.selector) {
            context.registerCheck(FuzzChecks.check_orderFulfilled.selector);
        } else if (
            _action ==
            context.seaport.fulfillBasicOrder_efficient_6GL6yc.selector
        ) {
            context.registerCheck(FuzzChecks.check_orderFulfilled.selector);
        } else if (_action == context.seaport.fulfillAvailableOrders.selector) {
            context.registerCheck(FuzzChecks.check_allOrdersFilled.selector);
        } else if (
            _action == context.seaport.fulfillAvailableAdvancedOrders.selector
        ) {
            context.registerCheck(FuzzChecks.check_allOrdersFilled.selector);
        } else if (_action == context.seaport.matchOrders.selector) {
            // Add match-specific checks
        } else if (_action == context.seaport.matchAdvancedOrders.selector) {
            // Add match-specific checks
        } else if (_action == context.seaport.cancel.selector) {
            context.registerCheck(FuzzChecks.check_orderCancelled.selector);
        } else if (_action == context.seaport.validate.selector) {
            context.registerCheck(FuzzChecks.check_orderValidated.selector);
        } else {
            revert("FuzzEngine: Action not implemented");
        }
    }
}

test/foundry/new/helpers/FuzzTestContext.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import { Vm } from "forge-std/Vm.sol";

import { StdCheats } from "forge-std/StdCheats.sol";

import { LibPRNG } from "solady/src/utils/LibPRNG.sol";

import {
    AdvancedOrderLib,
    BasicOrderParametersLib,
    MatchComponent
} from "seaport-sol/src/SeaportSol.sol";

import {
    AdvancedOrder,
    BasicOrderParameters,
    CriteriaResolver,
    Execution,
    Fulfillment,
    FulfillmentComponent,
    OrderParameters
} from "seaport-sol/src/SeaportStructs.sol";

import { ItemType, OrderType, Side } from "seaport-sol/src/SeaportEnums.sol";

import {
    BroadOrderType,
    OrderStatusEnum,
    SignatureMethod,
    UnavailableReason
} from "seaport-sol/src/SpaceEnums.sol";

import { AdvancedOrdersSpace } from "seaport-sol/src/StructSpace.sol";

import { OrderDetails } from "seaport-sol/src/fulfillments/lib/Structs.sol";

import {
    AmountDeriverHelper
} from "seaport-sol/src/lib/fulfillment/AmountDeriverHelper.sol";

import {
    ConduitControllerInterface
} from "seaport-sol/src/ConduitControllerInterface.sol";

import { SeaportInterface } from "seaport-sol/src/SeaportInterface.sol";

import { Result } from "./FuzzHelpers.sol";

import { ExpectedBalances } from "./ExpectedBalances.sol";

import { CriteriaResolverHelper } from "./CriteriaResolverHelper.sol";

import {
    FuzzGeneratorContext,
    FuzzGeneratorContextLib
} from "./FuzzGeneratorContextLib.sol";

import { TestStateGenerator } from "./FuzzGenerators.sol";

import { Failure } from "./FuzzMutationSelectorLib.sol";

import { FractionResults } from "./FractionUtil.sol";

import {
    ErrorsAndWarnings,
    SeaportValidatorInterface
} from "../../../../contracts/helpers/order-validator/SeaportValidator.sol";

import {
    SeaportNavigatorInterface
} from "../../../../contracts/helpers/navigator/SeaportNavigator.sol";

interface TestHelpers {
    function balanceChecker() external view returns (ExpectedBalances);

    function amountDeriverHelper() external view returns (AmountDeriverHelper);

    function criteriaResolverHelper()
        external
        view
        returns (CriteriaResolverHelper);

    function makeAccountWrapper(
        string memory name
    ) external view returns (StdCheats.Account memory);

    function getNaiveFulfillmentComponents(
        OrderDetails[] memory orderDetails
    )
        external
        returns (
            FulfillmentComponent[][] memory offer,
            FulfillmentComponent[][] memory consideration
        );

    function getMatchedFulfillments(
        AdvancedOrder[] memory orders,
        CriteriaResolver[] memory resolvers
    )
        external
        returns (
            Fulfillment[] memory fulfillments,
            MatchComponent[] memory remainingOfferComponents,
            MatchComponent[] memory remainingConsiderationComponents
        );

    function getMatchedFulfillments(
        OrderDetails[] memory orders
    )
        external
        returns (
            Fulfillment[] memory fulfillments,
            MatchComponent[] memory remainingOfferComponents,
            MatchComponent[] memory remainingConsiderationComponents
        );

    function allocateTokensAndApprovals(address _to, uint128 _amount) external;
}

struct FuzzParams {
    uint256 seed;
    uint256 totalOrders;
    uint256 maxOfferItems;
    uint256 maxConsiderationItems;
    bytes seedInput;
}

struct ReturnValues {
    bool fulfilled;
    bool cancelled;
    bool validated;
    bool[] availableOrders;
    Execution[] executions;
}

/**
 * @dev Context data related to post-execution expectations.
 */
struct Expectations {
    /**
     * @dev Expected zone calldata hashes.
     */
    bytes32[] expectedZoneCalldataHash;
    /**
     * @dev Expected contract order calldata hashes. Index 0 of the outer array
     *      corresponds to the generateOrder hash, while index 1 corresponds to
     *      the ratifyOrder hash.
     */
    bytes32[2][] expectedContractOrderCalldataHashes;
    /**
     * @dev Expected Result state for each order. Indexes correspond to the
     *      indexes of the orders in the orders array.
     */
    Result[] expectedResults;
    /**
     * @dev Expected executions.  Implicit means it doesn't correspond directly
     *      with a fulfillment that was passed in.
     */
    Execution[] expectedImplicitPreExecutions;
    Execution[] expectedImplicitPostExecutions;
    Execution[] expectedExplicitExecutions;
    Execution[] allExpectedExecutions;
    // /**
    //  * @dev Whether an order is available and will be fulfilled. Indexes
    //  *      correspond to order indexes in the orders array.
    //  */
    // bool[] expectedAvailableOrders;
    /**
     * @dev Expected event hashes. Encompasses all events that match watched
     *      topic0s.
     */
    bytes32[] expectedTransferEventHashes;
    /**
     * @dev Expected event hashes. Encompasses all events that match watched
     *      topic0s.
     */
    bytes32[] expectedSeaportEventHashes;
    bool[] ineligibleOrders;
    bool[] ineligibleFailures;
    /**
     * @dev Number of expected implicit native executions.
     */
    uint256 expectedImpliedNativeExecutions;
    /**
     * @dev Amount of native tokens we expect to be returned to the caller.
     */
    uint256 expectedNativeTokensReturned;
    /**
     * @dev Minimum msg.value that must be provided by caller.
     */
    uint256 minimumValue;
    FractionResults[] expectedFillFractions;
}

/**
 * @dev Context data related to test execution
 */
struct ExecutionState {
    /**
     * @dev A caller address. If this is nonzero, the FuzzEngine will prank this
     *      address before calling exec.
     */
    address caller;
    uint256 contractOffererNonce;
    /**
     * @dev A recipient address to be passed into fulfillAdvancedOrder,
     *      fulfillAvailableAdvancedOrders, or matchAdvancedOrders. Speciying a
     *      recipient on the fulfill functions will set that address as the
     *      recipient for all received items.  Specifying a recipient on the
     *      match function will set that address as the recipient for all
     *      unspent offer item amounts.
     */
    address recipient;
    /**
     * @dev A counter that can be incremented to cancel all orders made with
     *      the same counter value.
     */
    uint256 counter;
    /**
     * @dev Indicates what conduit, if any, to check for token approvals. A zero
     *      value means no conduit, look to seaport itself.
     */
    bytes32 fulfillerConduitKey;
    /**
     * @dev A struct containing basic order parameters that are used in the
     *      fulfillBasic functions.
     */
    BasicOrderParameters basicOrderParameters;
    /**
     * @dev An array of AdvancedOrders
     */
    AdvancedOrder[] orders;
    OrderDetails[] orderDetails;
    /**
     * @dev A copy of the original orders array. Modify this when calling
     *      previewOrder on contract orders and use it to derive order
     *      details (which is used to derive fulfillments and executions).
     */
    AdvancedOrder[] previewedOrders;
    /**
     * @dev An array of CriteriaResolvers. These allow specification of an
     *      order, offer or consideration, an identifier, and a proof.  They
     *      enable trait offer and collection offers, etc.
     */
    CriteriaResolver[] criteriaResolvers;
    /**
     * @dev An array of Fulfillments. These are used in the match functions to
     *      point offers and considerations to one another.
     */
    Fulfillment[] fulfillments;
    /**
     * @dev offer components not explicitly supplied in match fulfillments.
     */
    FulfillmentComponent[] remainingOfferComponents;
    bool hasRemainders;
    /**
     * @dev An array of FulfillmentComponents. These are used in the
     *      fulfillAvailable functions to set up aggregations.
     */
    FulfillmentComponent[][] offerFulfillments;
    FulfillmentComponent[][] considerationFulfillments;
    /**
     * @dev The maximum number of fulfillments to attempt in the
     *      fulfillAvailable functions.
     */
    uint256 maximumFulfilled;
    /**
     * @dev Status of each order before execution.
     */
    OrderStatusEnum[] preExecOrderStatuses;
    uint256 value;
    /**
     * @dev ErrorsAndWarnings returned from SeaportValidator.
     */
    ErrorsAndWarnings[] validationErrors;
}

/**
 * @dev Context data related to failure mutations.
 */
struct MutationState {
    /**
     * @dev Copy of the order selected for mutation.
     */
    AdvancedOrder selectedOrder;
    /**
     * @dev Index of the selected order in the orders array.
     */
    uint256 selectedOrderIndex;
    bytes32 selectedOrderHash;
    Side side;
    CriteriaResolver selectedCriteriaResolver;
    uint256 selectedCriteriaResolverIndex;
    address selectedArbitraryAddress;
}

struct FuzzTestContext {
    /**
     * @dev Cached selector of the chosen Seaport action.
     */
    bytes4 _action;
    /**
     * @dev Whether a Seaport action has been selected. This boolean is used as
     *      a workaround to detect when the cached action is set, since the
     *      empty selector is a valid Seaport action (fulfill basic efficient).
     */
    bool actionSelected;
    /**
     * @dev A Seaport interface, either the reference or optimized version.
     */
    SeaportInterface seaport;
    /**
     * @dev A ConduitController interface.
     */
    ConduitControllerInterface conduitController;
    /**
     * @dev A SeaportValidator interface.
     */
    SeaportValidatorInterface seaportValidator;
    /**
     * @dev A SeaportNavigator interface.
     */
    SeaportNavigatorInterface seaportNavigator;
    /**
     * @dev A TestHelpers interface. These helper functions are used to generate
     *      accounts and fulfillments.
     */
    TestHelpers testHelpers;
    /**
     * @dev A struct containing fuzzed params generated by the Foundry fuzzer.
     */
    FuzzParams fuzzParams;
    /**
     * @dev A struct containing the state for the execution phase.
     */
    ExecutionState executionState;
    /**
     * @dev Return values from the last call to exec. Superset of return values
     *      from all Seaport functions.
     */
    ReturnValues returnValues;
    /**
     * @dev Actual events emitted.
     */
    Vm.Log[] actualEvents;
    /**
     * @dev A struct containing expectations for the test. These are used to
     *      make assertions about the resulting test state.
     */
    Expectations expectations;
    /**
     * @dev An array of function selectors for "checks". The FuzzEngine will
     *      call these functions after calling exec to make assertions about
     *      the resulting test state.
     */
    bytes4[] checks;
    /**
     * @dev A struct containing the context for the FuzzGenerator. This is used
     *      upstream to generate the order state and is included here for use
     *      and reference throughout the rest of the lifecycle.
     */
    FuzzGeneratorContext generatorContext;
    /**
     * @dev The AdvancedOrdersSpace used to generate the orders. A nested struct
     *      of enums defining the selected permutation of orders.
     */
    AdvancedOrdersSpace advancedOrdersSpace;
}

/**
 * @notice Builder library for FuzzTestContext.
 */
library FuzzTestContextLib {
    using AdvancedOrderLib for AdvancedOrder;
    using AdvancedOrderLib for AdvancedOrder[];
    using BasicOrderParametersLib for BasicOrderParameters;
    using FuzzTestContextLib for FuzzTestContext;
    using LibPRNG for LibPRNG.PRNG;
    using FuzzGeneratorContextLib for FuzzGeneratorContext;

    /**
     * @dev Create an empty FuzzTestContext.
     *
     * @custom:return emptyContext the empty FuzzTestContext
     */
    function empty() internal returns (FuzzTestContext memory) {
        AdvancedOrder[] memory orders;
        CriteriaResolver[] memory resolvers;
        Fulfillment[] memory fulfillments;
        FulfillmentComponent[] memory components;
        FulfillmentComponent[][] memory componentsArray;
        Result[] memory results;
        bool[] memory available;
        Execution[] memory executions;
        bytes32[] memory hashes;
        bytes32[] memory expectedTransferEventHashes;
        bytes32[] memory expectedSeaportEventHashes;
        Vm.Log[] memory actualEvents;

        return
            FuzzTestContext({
                _action: bytes4(0),
                actionSelected: false,
                seaport: SeaportInterface(address(0)),
                conduitController: ConduitControllerInterface(address(0)),
                seaportValidator: SeaportValidatorInterface(address(0)),
                seaportNavigator: SeaportNavigatorInterface(address(0)),
                fuzzParams: FuzzParams({
                    seed: 0,
                    totalOrders: 0,
                    maxOfferItems: 0,
                    maxConsiderationItems: 0,
                    seedInput: ""
                }),
                checks: new bytes4[](0),
                returnValues: ReturnValues({
                    fulfilled: false,
                    cancelled: false,
                    validated: false,
                    availableOrders: available,
                    executions: executions
                }),
                expectations: Expectations({
                    expectedZoneCalldataHash: hashes,
                    expectedContractOrderCalldataHashes: new bytes32[2][](0),
                    expectedImplicitPreExecutions: new Execution[](0),
                    expectedImplicitPostExecutions: new Execution[](0),
                    expectedExplicitExecutions: new Execution[](0),
                    allExpectedExecutions: new Execution[](0),
                    expectedResults: results,
                    // expectedAvailableOrders: new bool[](0),
                    expectedTransferEventHashes: expectedTransferEventHashes,
                    expectedSeaportEventHashes: expectedSeaportEventHashes,
                    ineligibleOrders: new bool[](orders.length),
                    ineligibleFailures: new bool[](uint256(Failure.length)),
                    expectedImpliedNativeExecutions: 0,
                    expectedNativeTokensReturned: 0,
                    minimumValue: 0,
                    expectedFillFractions: new FractionResults[](orders.length)
                }),
                executionState: ExecutionState({
                    caller: address(0),
                    contractOffererNonce: 0,
                    recipient: address(0),
                    counter: 0,
                    fulfillerConduitKey: bytes32(0),
                    basicOrderParameters: BasicOrderParametersLib.empty(),
                    preExecOrderStatuses: new OrderStatusEnum[](0),
                    previewedOrders: orders,
                    orders: orders,
                    orderDetails: new OrderDetails[](0),
                    criteriaResolvers: resolvers,
                    fulfillments: fulfillments,
                    remainingOfferComponents: components,
                    hasRemainders: false,
                    offerFulfillments: componentsArray,
                    considerationFulfillments: componentsArray,
                    maximumFulfilled: 0,
                    value: 0,
                    validationErrors: new ErrorsAndWarnings[](orders.length)
                }),
                actualEvents: actualEvents,
                testHelpers: TestHelpers(address(this)),
                generatorContext: FuzzGeneratorContextLib.empty(),
                advancedOrdersSpace: TestStateGenerator.empty()
            });
    }

    /**
     * @dev Create a FuzzTestContext from the given partial arguments.
     *
     * @param orders the AdvancedOrder[] to set
     * @param seaport the SeaportInterface to set
     * @param caller the caller address to set
     * @custom:return _context the FuzzTestContext
     */
    function from(
        AdvancedOrder[] memory orders,
        SeaportInterface seaport,
        address caller
    ) internal returns (FuzzTestContext memory) {
        return
            empty()
                .withOrders(orders)
                .withSeaport(seaport)
                .withOrderHashes()
                .withCaller(caller)
                .withPreviewedOrders(orders.copy())
                .withProvisionedIneligbleOrdersArray();
    }

    /**
     * @dev Create a FuzzTestContext from the given partial arguments.
     *
     * @param orders the AdvancedOrder[] to set
     * @param seaport the SeaportInterface to set
     * @custom:return _context the FuzzTestContext
     */
    function from(
        AdvancedOrder[] memory orders,
        SeaportInterface seaport
    ) internal returns (FuzzTestContext memory) {
        return
            empty()
                .withOrders(orders)
                .withSeaport(seaport)
                .withOrderHashes()
                .withPreviewedOrders(orders.copy())
                .withProvisionedIneligbleOrdersArray();
    }

    /**
     * @dev Sets the orders on a FuzzTestContext
     *
     * @param context the FuzzTestContext to set the orders of
     * @param orders the AdvancedOrder[] to set
     *
     * @return _context the FuzzTestContext with the orders set
     */
    function withOrders(
        FuzzTestContext memory context,
        AdvancedOrder[] memory orders
    ) internal pure returns (FuzzTestContext memory) {
        context.executionState.orders = orders.copy();

        // Bootstrap with all available to ease direct testing.
        if (context.executionState.orderDetails.length == 0) {
            context.executionState.orderDetails = new OrderDetails[](
                orders.length
            );
            context.executionState.validationErrors = new ErrorsAndWarnings[](
                orders.length
            );
            for (uint256 i = 0; i < orders.length; ++i) {
                context
                    .executionState
                    .orderDetails[i]
                    .unavailableReason = UnavailableReason.AVAILABLE;
            }
        }

        context.expectations.expectedFillFractions = (
            new FractionResults[](orders.length)
        );

