            parameters: OrderParametersLib
                .empty()
                .withOffer(
                    SeaportArrays.OfferItems(
                        OfferItemLib
                            .empty()
                            .withToken(address(erc20s[1]))
                            .withAmount(101)
                    )
                )
                .withTotalConsideration(
                    SeaportArrays.ConsiderationItems(
                        ConsiderationItemLib
                            .empty()
                            .withToken(address(erc20s[0]))
                            .withAmount(101)
                    )
                ),
            signature: ""
        });

