                            }),
                            FulfillmentComponent({
                                orderIndex: 3,
                                itemIndex: 0
                            })
                        )
                })
            );
        } else {
            // [
            //     ([(1, 0)], [(0, 0), (2, 0)]),
            //     ([(3, 0)], [(0, 0)]),
            //     ([(0, 0)], [(1, 0), (3, 0)]),
            //     ([(2, 0)], [(1, 0)])
            // ]
            expectedFulfillments = SeaportArrays.Fulfillments(
                Fulfillment({
                    offerComponents: SeaportArrays.FulfillmentComponents(
