                    ),
                    considerationComponents: SeaportArrays
                        .FulfillmentComponents(
                            FulfillmentComponent({
                                orderIndex: 1,
                                itemIndex: 0
                            })
                        )
                })
            );
        }

        bytes32[] memory orderHashes = new bytes32[](4);

        (Fulfillment[] memory fulfillments, , ) = matcher
            .getMatchedFulfillments(
                SeaportArrays.Orders(
                    orderOne,
                    otherOrderOne,
                    orderTwo,
                    otherOrderTwo
                ),
