                expectedFulfillments[0],
                "fulfillments[0]"
            );
            assertEq(
                fulfillments[1],
                expectedFulfillments[1],
                "fulfillments[1]"
            );
            assertEq(
                fulfillments[2],
                expectedFulfillments[2],
                "fulfillments[2]"
            );
            assertEq(
                fulfillments[3],
                expectedFulfillments[3],
                "fulfillments[3]"
            );
