                numerator: numerator,
                denominator: denominator,
                startAmount: startAmount,
                endAmount: endAmount,
                startTime: startTime,
                endTime: endTime,
                roundUp: roundUp // round up considerations
            });
    }

    function getFraction(
        uint256 numerator,
        uint256 denominator,
        uint256 value
    ) public pure returns (uint256) {
        return
            _getFraction({
                numerator: numerator,
                denominator: denominator,
                value: value
            });
    }

    function locateCurrentAmount(
        uint256 startAmount,
        uint256 endAmount,
        uint256 startTime,
        uint256 endTime,
        bool roundUp
    ) public view returns (uint256) {
